10	/**
11	 * Rejects a create-owner request that is missing or blank in any mandatory field, before the body is
12	 * mapped to an entity. Binds the request body (the single {@code @RequestBody} step of this pipeline)
13	 * and republishes it as a variable for the later steps.
14	 */
15	public class RequireOwnerFields {
16	
17	    public void service(@RequestBody OwnerFieldsDto request, Out<OwnerFieldsDto> validated)
18	            throws MissingOwnerFieldsException {
19	        List<String> missing = new ArrayList<>();
20	        if (isBlank(request.getFirstName())) {
21	            missing.add("firstName");
22	        }
23	        if (isBlank(request.getLastName())) {
24	            missing.add("lastName");
25	        }
26	        if (isBlank(request.getAddress())) {
27	            missing.add("address");
28	        }
29	        if (isBlank(request.getCity())) {
30	            missing.add("city");
31	        }
32	        if (isBlank(request.getTelephone())) {
33	            missing.add("telephone");
34	        }
35	        if (!missing.isEmpty()) {
36	            throw new MissingOwnerFieldsException(missing);
37	        }
38	        validated.set(request);
39	    }
40	
41	    private static boolean isBlank(String value) {
42	        return value == null || value.isBlank();
43	    }
44	}
