6	/**
7	 * Normalizes a create-owner request's telephone to E.164 form: a leading {@code '+'} and country code
8	 * are kept when present, otherwise country code {@code '+61'} is assumed and a single leading
9	 * {@code '0'} is dropped from the national digits; spaces, dashes and brackets are stripped and 8 to 15
10	 * digits are required after the {@code '+'}. So {@code '0412 345 678'} becomes {@code '+61412345678'}.
11	 * The normalized value is written back onto the request (the same object the later {@link BuildOwner}
12	 * step maps to the entity), so it is stored and returned as {@code telephone}. A number that cannot
13	 * form valid E.164 is rejected via {@link InvalidTelephoneException}, which the global handler turns
14	 * into a 400.
15	 */
16	public class NormalizeTelephone {
17	
18	    public void service(@Val OwnerFieldsDto request) throws InvalidTelephoneException {
19	        request.setTelephone(TelephoneE164.normalize(request.getTelephone()));
20	    }
21	}
