1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.util.Locale;
4	import java.util.regex.Pattern;
5	
6	import net.officefloor.plugin.variable.Val;
7	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
8	
9	/**
10	 * Normalizes an owner request's optional {@code email}. Email is optional, so an absent or blank
11	 * value is left untouched. When present it must be a syntactically valid address; otherwise the
12	 * request is rejected via {@link InvalidEmailException}, which the global handler turns into a 400.
13	 * A valid value is lower-cased and written back onto the request (the same object the later
14	 * {@link BuildOwner}/{@link ApplyOwner} step maps to the entity), so it is stored and returned
15	 * lower-cased as {@code email}.
16	 */
17	public class NormalizeEmail {
18	
19	    /** A basic syntactic check: non-empty local part, '@', domain with at least one dot. */
20	    private static final Pattern EMAIL = Pattern.compile("^[^\\s@]+@[^\\s@]+\\.[^\\s@]+$");
21	
22	    public void service(@Val OwnerFieldsDto request) throws InvalidEmailException {
23	        String raw = request.getEmail();
24	        if (raw == null || raw.isBlank()) {
25	            return;
26	        }
27	        String email = raw.trim();
28	        if (!EMAIL.matcher(email).matches()) {
29	            throw new InvalidEmailException(raw);
30	        }
31	        request.setEmail(email.toLowerCase(Locale.ROOT));
32	    }
33	}
