1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	import org.springframework.samples.petclinic.repository.OwnerRepository;
6	
7	/**
8	 * Assigns the {@code customerCode} formatted {@code <LAST3>-<NNNN>}, where LAST3 is the
9	 * upper-cased first three letters of the owner's last name and NNNN is a global 4-digit
10	 * zero-padded sequence equal to one more than the current number of owners.
11	 */
12	public class AssignCustomerCode {
13	
14	    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
15	        String lastName = owner.getLastName() == null ? "" : owner.getLastName();
16	        String last3 = lastName.length() >= 3 ? lastName.substring(0, 3) : lastName;
17	        int sequence = ownerRepository.findAll().size() + 1;
18	        owner.setCustomerCode(String.format("%s-%04d", last3.toUpperCase(), sequence));
19	    }
20	}
